  const mod = await import(pathToFileURL(pluginPath).href);
  const plugin = mod.default ?? mod;
  const result = (typeof plugin[stage] === 'function' ? plugin[stage](ctx) : undefined) ?? null;
  parentPort.postMessage({ ok: true, result });
