function findWorkspaceRoot(fromPath: string): string {
  let dir = dirname(resolvePath(fromPath));
  while (dir !== dirname(dir)) {
    if (existsSync(join(dir, "pnpm-workspace.yaml"))) return dir;
    dir = dirname(dir);
  }
  return dir;
}

